INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 0, "", 15, 30000, 0, 0, "", 1, 2, 35);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 0, "", 1, 40000, 0, 0, "", 100, 8, 36);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 1, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 1, 40001, 0, 107501, "ぺコリーヌ", 150, 8, 37);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 1, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 2, 40001, 0, 107601, "コッコロ", 150, 8, 38);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 1, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 3, 40001, 0, 107801, "キャル", 150, 8, 39);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 1, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 4, 40001, 0, 107701, "スズメ", 150, 8, 40);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 1, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 5, 40001, 0, 107901, "タマキ", 150, 8, 41);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 2, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 6, 40001, 0, 107501, "ぺコリーヌ", 150, 8, 42);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 2, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 7, 40001, 0, 107601, "コッコロ", 150, 8, 43);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 2, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 8, 40001, 0, 107801, "キャル", 150, 8, 44);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 2, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 9, 40001, 0, 107701, "スズメ", 150, 8, 45);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 2, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 10, 40001, 0, 107901, "タマキ", 150, 8, 46);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (91002, 0, "", 1, 40003, 0, 0, "", 150, 8, 57);
