INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (23001, 0, "", 10, 20001, 0, 0, "", 20, 2, 320);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 40011, 0, 125801, "リリ", 1, 2, 321);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 1, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2, 40011, 0, 126001, "クリア", 1, 2, 322);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 1, "んーと。\nこれ、あげる。\nはい", 3, 40011, 0, 126101, "プレシア", 1, 2, 323);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 2, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 4, 40011, 0, 125801, "リリ", 1, 2, 324);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 2, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 5, 40011, 0, 126001, "クリア", 1, 2, 325);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 2, "お兄。\nきてくれて、うれしい", 6, 40011, 0, 126101, "プレシア", 1, 2, 326);
